/**
 * Room tile geometry, extracted from the client's own casts.
 *
 * Generated by `tools/extract-room-geometry.mjs` from each room cast's
 * `room.<name>.object.xml`. Keyed by the cast/room NAME (`vmk_esplanade`), which
 * is what `room.code.<N>` gives us — so `ROOM_CODES.get(code)` is the lookup key.
 *
 * ⚠ WHY THE SERVER NEEDS THIS AT ALL: `CRoomFactorAvatar.WalkToTile` is a
 * SINGLE-HOP animation. It lerps from the avatar's current position to one
 * target and has no route logic whatsoever — it even snaps outright when source
 * and target share x/y. So pathfinding is the SERVER's job: to make a player
 * walk, we send `2583 _StatusPulse` once per step along a route we compute here.
 * Sending a single pulse with a distant destination makes the avatar slide or
 * teleport, which is exactly how it looked before this existed.
 */
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const GEOMETRY_PATH =
  process.env.VMK_ROOM_GEOMETRY ?? join(here, "..", "..", "assets", "room-geometry.json");

interface RawRoom {
  name: string;
  tileSize: number;
  tileCount: number;
  spawnTile: number;
  spawnFrom: string;
  doors: Array<{ id: number; tiles: number[]; middle: number }>;
  /** Flat [ref, x, y, z, ...] in ABSOLUTE room space (floor offset included). */
  tiles: number[];
  /** Parallel to `tiles`: which floor each tile is on. Absent in old extracts. */
  floorOf?: number[];
  /** Disney's `<LINKS>`: the only walkable steps between two floors. */
  links?: Array<[number, number]>;
  /** Non-empty tile NAMEs by ref (`sit10`, `open_navigator`, ...). */
  names?: Record<string, string>;
}

interface Room {
  name: string;
  tileSize: number;
  spawnTile: number;
  /** tile ref -> neighbouring tile refs (8-way). Built on first use. */
  neighbours: Map<number, number[]>;
  /** tile ref -> world [x, y, z], needed to work out which way a step faces. */
  coords: Map<number, [number, number, number]>;
  /** Tiles the layout marks CLASS "exit". Where they lead is room-exits.ts. */
  exits: Set<number>;
  /** Exit tile -> its door ID (the `ID=` room handlers switch exits on and off by). */
  exitIds: Map<number, number>;
  /** `x,y` -> every tile ref in that column (stacked floors share one). */
  byXY: Map<string, number[]>;
  floorOf: Map<number, number>;
  /** Tile ref -> its layout NAME (`podium`, `sit10`, ...), where it has one. */
  names: Map<number, string>;
  has(ref: number): boolean;
}

const raw = new Map<string, RawRoom>();
const built = new Map<string, Room>();
/** Seasonal builds whose layout differs from the everyday room, by cast folder. */
const variants = new Map<string, RawRoom>();
let loaded = false;

/** The layout a seasonal cast brings, if it differs from the everyday room's. */
export function seasonalLayout(castKey: string): { name: string; tiles: number[]; names?: Record<string, string> } | null {
  load();
  return variants.get(castKey) ?? null;
}

/**
 * Walk `roomName` on a seasonal build's layout instead of the everyday one
 * (`VMK_SEASON`, see seasons.ts). Everything tile-based follows: pathing,
 * spawn, doors, seats named in the layout.
 */
export function seasonalTileMap(roomName: string, castKey: string): ((tile: number) => number | null) | null {
  load();
  const from = raw.get(roomName);
  const to = variants.get(castKey);
  if (!from || !to || to.name !== roomName) return null;
  const doorTiles = (r: RawRoom) => new Set(r.doors.flatMap((d) => d.tiles));
  const fromDoors = doorTiles(from);
  const toDoors = doorTiles(to);
  const at = new Map<string, number>();
  for (let i = 0; i < to.tiles.length; i += 4) at.set(`${to.tiles[i + 1]},${to.tiles[i + 2]},${to.tiles[i + 3]}`, to.tiles[i]);
  const where = new Map<number, string>();
  for (let i = 0; i < from.tiles.length; i += 4) where.set(from.tiles[i], `${from.tiles[i + 1]},${from.tiles[i + 2]},${from.tiles[i + 3]}`);
  // Same spot, same kind: a doorway only maps onto a doorway. Central Plaza's
  // Magic Shop door (tiles 1, 2) is plain floor in the seasonal builds, and
  // must not become a door to a shop the room has no entrance for.
  return (tile) => {
    const key = where.get(tile);
    const next = key === undefined ? undefined : at.get(key);
    if (next === undefined) return null;
    if (fromDoors.has(tile) && !toDoors.has(next)) return null;
    return next;
  };
}

export function useSeasonalLayout(roomName: string, castKey: string): boolean {
  load();
  const layout = variants.get(castKey);
  if (!layout || layout.name !== roomName) return false;
  raw.set(roomName, layout);
  built.delete(roomName);
  return true;
}

function load(): void {
  if (loaded) return;
  loaded = true;
  if (!existsSync(GEOMETRY_PATH)) {
    console.warn(
      `[geometry] ${GEOMETRY_PATH} not found — walking will fall back to a single hop. ` +
        `Run: node tools/extract-room-geometry.mjs`,
    );
    return;
  }
  try {
    const parsed = JSON.parse(readFileSync(GEOMETRY_PATH, "utf8")) as {
      rooms: Record<string, RawRoom>;
      variants?: Record<string, RawRoom>;
    };
    for (const [name, room] of Object.entries(parsed.rooms)) raw.set(name, room);
    for (const [cast, room] of Object.entries(parsed.variants ?? {})) variants.set(cast, room);
    console.log(`[geometry] ${raw.size} rooms loaded from ${GEOMETRY_PATH}`);
  } catch (error) {
    console.warn(`[geometry] could not read ${GEOMETRY_PATH}: ${(error as Error).message}`);
  }
}

/** Build the 8-way adjacency graph for one room, once. */
function room(name: string | undefined): Room | null {
  if (!name) return null;
  load();
  const cached = built.get(name);
  if (cached) return cached;
  const source = raw.get(name);
  if (!source) return null;

  // ⚠ A COLUMN PER (X, Y), NOT A TILE. Multi-level rooms stack tiles on the
  // same footprint at different Z — Space Mountain has floors at Z=208 and
  // Z=294, Haunted Mansion one per level. Mapping `x,y -> ref` overwrites, so
  // every stacked tile but one becomes unreachable and the room shatters into
  // islands. That was 5538 stranded tiles across 52 rooms.
  //
  // ⚠ AND A TILE BELONGS TO ONE FLOOR. Stacked floors only ever meet through
  // `<LINKS>` (stairs); two floors that happen to come within a step of each
  // other in space are still not walkable into one another — the Haunted
  // Mansion attic's levels are 144 apart, Tomorrowland Hub's 210, and in the
  // original you crossed them by an exit, not on foot.
  const byXY = new Map<string, number[]>();
  const coords = new Map<number, [number, number, number]>();
  const floorOf = new Map<number, number>();
  for (let i = 0; i < source.tiles.length; i += 4) {
    const ref = source.tiles[i];
    floorOf.set(ref, source.floorOf?.[i / 4] ?? -1);
    const x = source.tiles[i + 1];
    const y = source.tiles[i + 2];
    const z = source.tiles[i + 3];
    const key = `${x},${y}`;
    const column = byXY.get(key);
    if (column) column.push(ref);
    else byXY.set(key, [ref]);
    coords.set(ref, [x, y, z]);
  }

  const s = source.tileSize;
  /**
   * Which tiles count as adjacent for walking.
   *
   * ⚠ THE CLIENT'S LERP IS A FIXED 500 ms PER HOP (`m_iStatusDelay`, assigned
   * once in `CRoomFactorAvatar.construct` and never reassigned by anything).
   * So the server cannot vary walk speed — every step must cover the SAME
   * screen distance or the avatar visibly changes pace mid-walk.
   *
   * On this lattice a tile is a rhombus twice as wide as it is tall
   * (`screenX = x - y`, `screenY = 0.5(x + y)`), so with tileSize 24:
   *
   *   world (±s, 0) / (0, ±s)   share an EDGE     screen 26.8 px
   *   world (±s, ±s)            share a VERTEX    screen 24.0 px
   *   world (±s, ∓s)            share a VERTEX    screen 48.0 px  ← 2x
   *
   * ⚠ EIGHT-WAY IS CORRECT HERE, despite the uneven step lengths. Restricting
   * to the four edge neighbours does make every hop 26.8 px, but it cannot
   * express a straight screen-horizontal walk: going right becomes an
   * alternation of down-right and up-right, so the route visibly zigzags AND
   * the avatar's facing flips every single step. That reads far worse than the
   * pace change it was meant to cure, and it is not how the original behaved.
   *
   * The pace variation is inherent to the client: `m_iStatusDelay` is a fixed
   * 500 ms per hop whatever the distance, so the original game had it too.
   *
   * `VMK_TILE_ADJACENCY=4` restores edge-only for comparison.
   */
  const offsets: Array<[number, number]> =
    process.env.VMK_TILE_ADJACENCY === "4"
      ? [[s, 0], [-s, 0], [0, s], [0, -s]]
      : [[s, 0], [-s, 0], [0, s], [0, -s], [s, s], [s, -s], [-s, s], [-s, -s]];
  // No height limit WITHIN a floor. A floor is one surface Disney authored,
  // stairs included: the Haunted Mansion's stairs climb 14..26 per step on a
  // 16-unit grid, so the old "one tile's height" cutoff broke every staircase
  // in two. Separate levels are separate floors, which is what keeps them apart.
  const slack = Number(process.env.VMK_TILE_SLACK ?? Math.floor(s / 4));
  const near = (x: number, y: number): number[] => {
    const exact = byXY.get(`${x},${y}`);
    if (exact) return exact;
    let best: number[] = [];
    let bestDistance = Infinity;
    for (let ox = -slack; ox <= slack; ox++) {
      for (let oy = -slack; oy <= slack; oy++) {
        const hit = byXY.get(`${x + ox},${y + oy}`);
        const d = ox * ox + oy * oy;
        if (hit && d < bestDistance) {
          best = hit;
          bestDistance = d;
        }
      }
    }
    return best;
  };
  const neighbours = new Map<number, number[]>();
  for (const [ref, [x, y]] of coords) {
    const list: number[] = [];
    for (const [dx, dy] of offsets) {
      for (const hit of near(x + dx, y + dy)) {
        const there = coords.get(hit);
        if (there && hit !== ref && floorOf.get(hit) === floorOf.get(ref) && !list.includes(hit)) list.push(hit);
      }
    }
    neighbours.set(ref, list);
  }
  for (const [ref, list] of neighbours) {
    for (const hit of list) {
      const back = neighbours.get(hit);
      if (back && !back.includes(ref)) back.push(ref);
    }
  }
  for (const [a, b] of source.links ?? []) {
    if (!coords.has(a) || !coords.has(b)) continue;
    const fromA = neighbours.get(a) as number[];
    const fromB = neighbours.get(b) as number[];
    if (!fromA.includes(b)) fromA.push(b);
    if (!fromB.includes(a)) fromB.push(a);
  }

  const value: Room = {
    name,
    tileSize: s,
    spawnTile: source.spawnTile,
    neighbours,
    coords,
    exits: new Set(source.doors.flatMap((d) => d.tiles)),
    exitIds: new Map(source.doors.flatMap((d) => d.tiles.map((t) => [t, d.id] as [number, number]))),
    byXY,
    floorOf,
    names: new Map(Object.entries(source.names ?? {}).map(([ref, name]) => [Number(ref), name])),
    has: (ref) => coords.has(ref),
  };
  built.set(name, value);
  return value;
}

/**
 * Which way an avatar faces when stepping from one tile to another, as the
 * 0..7 direction index the client's `Action` list wants.
 *
 * DERIVATION — none of this is guesswork, and all of it is checkable:
 *
 * 1. `RoomMath.AbsToScr` is the room's isometric projection:
 *        screenX = x - y          screenY = 0.5 * (x + y) - z
 *    so -x/-y is straight UP the screen and +x/+y is straight DOWN it, while
 *    -x/+y is pure LEFT and +x/-y is pure RIGHT.
 *
 * 2. `CAvatarFactor.construct` has `m_arFlipList = [0,1,2,3,4,3,2,1]`: art is
 *    drawn for directions 0..4 only, and 5/6/7 are 3/2/1 mirrored horizontally.
 *    So 0 and 4 are the two poses on the screen's vertical axis.
 *
 * 3. The art itself settles the rest. In `gfx_avatar_bodyparts`, `std_hd_1_0_0`
 *    is a symmetric back-of-head with both ears, `std_hd_1_4_0` is a symmetric
 *    face, and `std_hd_1_2_0` is a hard profile looking to the LEFT. Faces
 *    (`std_fc_*`) exist only for directions 2, 3 and 4 — the camera-facing half.
 *
 * Therefore 0 = away/up, 2 = screen-left, 4 = toward/down, 6 = screen-right,
 * i.e. the index runs COUNTER-clockwise on screen, and the diagonals fall out
 * of the projection above.
 *
 * Returns `null` when the tiles are unknown or identical, so callers can hold
 * whatever facing the avatar already had.
 */
/**
 * World tile delta -> direction index. The index runs CLOCKWISE on screen.
 *
 * Proven from the shoe artwork in `vmk_avatar_sh_1_2.cct` (`std_lsh_1_<dir>_0`),
 * which shows the foot far more legibly than the head does:
 *
 *   dir 0  heel toward the viewer, no toe visible   -> facing AWAY  (up-screen)
 *   dir 2  full profile, toe pointing RIGHT         -> facing RIGHT
 *   dir 4  front-on, laces and tongue visible       -> facing TOWARD (down-screen)
 *
 * So the authored half (0..4) faces rightward and `m_arFlipList` mirrors it into
 * 5..7 for the left. Every entry below is then fixed by the projection
 * (`screenX = x - y`, `screenY = 0.5(x + y)`): e.g. (1,-1) is pure screen-right
 * and maps to 2, (-1,1) is pure screen-left and maps to 6.
 */
const CLOCKWISE: Record<string, number> = {
  "-1,-1": 0, // screen up         (away from camera)
  "0,-1": 1, //  screen up-right
  "1,-1": 2, //  screen right
  "1,0": 3, //   screen down-right
  "1,1": 4, //   screen down       (toward camera)
  "0,1": 5, //   screen down-left
  "-1,1": 6, //  screen left
  "-1,0": 7, //  screen up-left
};

export function directionBetween(
  roomName: string | undefined,
  from: number,
  to: number,
): number | null {
  const r = room(roomName);
  const a = r?.coords.get(from);
  const b = r?.coords.get(to);
  if (!a || !b) return null;
  const dx = Math.sign(b[0] - a[0]);
  const dy = Math.sign(b[1] - a[1]);
  if (dx === 0 && dy === 0) return null;
  const dir = CLOCKWISE[`${dx},${dy}`];
  if (dir === undefined) return null;
  // Escape hatch kept only because this was got wrong twice before the shoe art
  // settled it; `ccw` mirrors 1..3 with 5..7 and leaves 0 and 4 alone.
  return process.env.VMK_TILE_DIRECTION === "ccw" ? (8 - dir) % 8 : dir;
}

/**
 * The tile one step from `from` in direction index `dir` (0..7, the same index
 * `directionBetween` returns), or null if there is none.
 *
 * Uses the walking graph, so a step up a cliff or onto another floor counts as
 * no tile at all, which is what a ride should do at the edge of the track.
 */
export function tileToward(roomName: string | undefined, from: number, dir: number): number | null {
  const r = room(roomName);
  const a = r?.coords.get(from);
  if (!r || !a) return null;
  for (const next of r.neighbours.get(from) ?? []) {
    const b = r.coords.get(next);
    if (b && directionBetween(roomName, from, next) === dir) return next;
  }
  return null;
}

export function tilesApart(roomName: string | undefined, a: number, b: number): number | null {
  const r = room(roomName);
  const p = r?.coords.get(a);
  const q = r?.coords.get(b);
  if (!r || !p || !q) return null;
  return Math.max(Math.abs(p[0] - q[0]), Math.abs(p[1] - q[1])) / r.tileSize;
}

/** A tile's layout NAME (`podium`, `sit10`, ...), or undefined if it has none. */
export function tileName(roomName: string | undefined, ref: number): string | undefined {
  return room(roomName)?.names.get(ref);
}

/** The first tile carrying a layout NAME, or null. */
/**
 * The NAME of the floor a tile is on (`<FLOOR NAME=…>` in the layout), e.g.
 * "pool" in the Waterpark Pool. Undefined when unknown.
 */
export function floorNameOf(roomName: string | undefined, ref: number): string | undefined {
  if (!roomName) return undefined;
  load();
  const source = raw.get(roomName) as (RawRoom & { floors?: Array<{ name?: string }> }) | undefined;
  if (!source?.floorOf || !source.floors) return undefined;
  for (let i = 0; i < source.tiles.length; i += 4) {
    if (source.tiles[i] === ref) return source.floors[source.floorOf[i / 4]]?.name;
  }
  return undefined;
}

const floorTiles = new Map<string, ReadonlySet<number>>();
/**
 * Every tile on the floor with this NAME, or an empty set. `floorNameOf` for
 * a whole route: a path search asks about every step it tries.
 */
export function tilesOnFloor(roomName: string | undefined, name: string): ReadonlySet<number> {
  if (!roomName) return new Set();
  const key = `${roomName}\0${name}`;
  const cached = floorTiles.get(key);
  if (cached) return cached;
  load();
  const source = raw.get(roomName) as (RawRoom & { floors?: Array<{ name?: string }> }) | undefined;
  const out = new Set<number>();
  if (source?.floorOf && source.floors) {
    for (let i = 0; i < source.tiles.length; i += 4) {
      if (source.floors[source.floorOf[i / 4]]?.name === name) out.add(source.tiles[i]);
    }
  }
  floorTiles.set(key, out);
  return out;
}

/** A tile's absolute world position — the client's `GetAbsPos` — or null. */
export function tileCoords(roomName: string | undefined, ref: number): [number, number, number] | null {
  return room(roomName)?.coords.get(ref) ?? null;
}

/** Every tile ref in a room, with its floor and walking neighbours. */
export function roomTiles(roomName: string | undefined): { ref: number; floor: number; neighbours: number[] }[] {
  const r = room(roomName);
  if (!r) return [];
  return [...r.coords.keys()].map((ref) => ({ ref, floor: r.floorOf.get(ref) ?? -1, neighbours: r.neighbours.get(ref) ?? [] }));
}

export function tileNamed(roomName: string | undefined, name: string): number | null {
  for (const [ref, tile] of room(roomName)?.names ?? []) if (tile === name) return ref;
  return null;
}

/**
 * The tile `dx`, `dy` whole tiles away from `from` in WORLD space, on the same
 * floor where the column has several, or null if there is none.
 *
 * Unlike `tileToward` this ignores the walking graph: it answers "what tile is
 * there", which is what `CRoomItemProximityConfig.GetSurroundingBlocks` asks
 * (`block + tileSize * direction * j`) when it lays out a dark-ride trigger zone.
 */
export function tileAtOffset(
  roomName: string | undefined,
  from: number,
  dx: number,
  dy: number,
): number | null {
  const r = room(roomName);
  const a = r?.coords.get(from);
  if (!r || !a) return null;
  const column = r.byXY.get(`${a[0] + dx * r.tileSize},${a[1] + dy * r.tileSize}`);
  if (!column?.length) return null;
  const floor = r.floorOf.get(from);
  return column.find((t) => r.floorOf.get(t) === floor) ?? column[0];
}

/**
 * The arrival tile for a room. `null` if the room has no geometry.
 *
 * The extractor picks this from the room's doorways, but a doorway tile is not
 * guaranteed to be somewhere you can walk OFF: `nautilus` spawns onto a tile
 * with no edge-neighbours at all, which strands the player the moment they
 * arrive. So the tile is validated here and, if it is a dead end, swapped for
 * the nearest one that connects to somewhere.
 */
export function spawnTileFor(roomName: string | undefined): number | null {
  const r = room(roomName);
  if (!r) return null;
  if ((r.neighbours.get(r.spawnTile)?.length ?? 0) > 0) return r.spawnTile;

  const from = r.coords.get(r.spawnTile);
  if (!from) return r.spawnTile;
  let best = r.spawnTile;
  let bestDistance = Infinity;
  for (const [ref, p] of r.coords) {
    if ((r.neighbours.get(ref)?.length ?? 0) === 0) continue;
    const d = (p[0] - from[0]) ** 2 + (p[1] - from[1]) ** 2 + (p[2] - from[2]) ** 2;
    if (d < bestDistance) {
      bestDistance = d;
      best = ref;
    }
  }
  return best;
}

/** The door ID of an exit tile, or null when `tile` is not an exit. */
export function exitIdAt(roomName: string | undefined, tile: number): number | null {
  return room(roomName)?.exitIds.get(tile) ?? null;
}

/** Every exit tile whose door ID is in `ids`. */
export function exitTilesWithIds(roomName: string | undefined, ids: Iterable<number>): number[] {
  const wanted = new Set(ids);
  const r = room(roomName);
  if (!r) return [];
  return [...r.exitIds].filter(([, id]) => wanted.has(id)).map(([tile]) => tile).sort((a, b) => a - b);
}

/**
 * The walkable tiles one step in from a doorway: neighbours of `doorTiles`
 * that are not exits themselves. Arriving ON a door tile stands you in the
 * doorway at the room's edge — through a train's doors, that reads as
 * standing outside the car.
 */
export function insideOf(roomName: string | undefined, doorTiles: number[]): number[] {
  const r = room(roomName);
  if (!r) return doorTiles;
  const inside = new Set<number>();
  for (const tile of doorTiles) {
    for (const next of r.neighbours.get(tile) ?? []) if (!r.exits.has(next)) inside.add(next);
  }
  return inside.size ? [...inside].sort((a, b) => a - b) : doorTiles;
}

/** Is `tile` one of the room's exit tiles (CLASS "exit")? */
export function isExitTile(roomName: string | undefined, tile: number): boolean {
  return room(roomName)?.exits.has(tile) ?? false;
}

/**
 * The nearest walkable tile to `preferred` that nobody is standing on.
 *
 * ⚠ Needed because `spawnTileFor` returns the SAME tile for everyone. Two
 * players entering a room both landed on it and rendered on top of each other,
 * which is the one case where VMK does let avatars overlap — because arrival
 * uses `SetToTileStack`, which places without any occupancy check.
 *
 * Falls back to `preferred` when the room is unknown or genuinely full.
 */
export function freeTileNear(
  roomName: string | undefined,
  preferred: number,
  occupied: ReadonlySet<number>,
): number {
  if (!occupied.has(preferred)) return preferred;
  const r = room(roomName);
  if (!r || !r.has(preferred)) return preferred;

  // Breadth-first outward, so the substitute is as close to the door as the
  // crowd allows rather than somewhere across the room.
  const seen = new Set<number>([preferred]);
  const queue: number[] = [preferred];
  while (queue.length) {
    const at = queue.shift() as number;
    if (!occupied.has(at)) return at;
    for (const next of r.neighbours.get(at) ?? []) {
      if (seen.has(next)) continue;
      seen.add(next);
      queue.push(next);
    }
  }
  return preferred;
}

/**
 * Breadth-first route from `from` to `to`, INCLUDING the destination but not the
 * starting tile — i.e. exactly the steps to emit as `_StatusPulse` messages.
 *
 * ⚠ NEVER RETURNS A JUMP. When the target cannot be reached, this walks to the
 * reachable tile physically closest to it instead of hopping straight there.
 * A `_StatusPulse` naming a distant tile does not fail — `WalkToTile` happily
 * lerps the avatar across the whole room in one 500 ms glide, which reads as
 * the player flying. Rooms genuinely do contain tiles you cannot walk to
 * (behind scenery, on another floor, decorative), so this is the normal case
 * for a stray click, not an error path.
 *
 * Returns `[]` when there is nowhere to go: already there, or no geometry.
 */
export function findPath(
  roomName: string | undefined,
  from: number,
  to: number,
  /**
   * Tiles other avatars are standing on. Two people never share a tile in VMK,
   * so these are impassable: not just as a destination but as a route, since
   * walking THROUGH someone looks just as wrong as stopping on top of them.
   */
  blocked: ReadonlySet<number> = new Set(),
  canStep?: (from: number, to: number) => boolean,
): number[] {
  if (from === to) return [];
  const r = room(roomName);
  // No geometry at all: refuse rather than teleport. A room we cannot route in
  // is one where every "walk" would be a glide across the floor.
  if (!r || !r.has(from)) return [];

  const previous = new Map<number, number>();
  const seen = new Set<number>([from]);
  const queue: number[] = [from];
  let found = false;
  while (queue.length) {
    const at = queue.shift() as number;
    if (at === to) {
      found = true;
      break;
    }
    for (const next of r.neighbours.get(at) ?? []) {
      if (seen.has(next) || blocked.has(next)) continue;
      if (canStep && !canStep(at, next)) continue;
      seen.add(next);
      previous.set(next, at);
      queue.push(next);
    }
  }

  let goal = to;
  if (!found) {
    // Get as close as the floor allows. `seen` is the whole reachable region by
    // now, since the search only stops early on success.
    const target = r.coords.get(to);
    if (!target) return [];
    let best: number | null = null;
    let bestDistance = Infinity;
    // ⚠ `from` MUST be a candidate. Excluding it forces a move even when the
    // tile you are already on is the closest the floor allows, and the tile you
    // get pushed to then has `from` as ITS closest — so clicking a blocked
    // target walks you 57 -> 73 -> 57 -> 73 forever. Standing still is the
    // correct answer to "get as close as you can" when you are already there;
    // the caller treats an empty path as "do not move".
    for (const ref of seen) {
      const p = r.coords.get(ref);
      if (!p) continue;
      const d =
        (p[0] - target[0]) ** 2 + (p[1] - target[1]) ** 2 + (p[2] - target[2]) ** 2;
      if (d < bestDistance) {
        bestDistance = d;
        best = ref;
      }
    }
    if (best === null || best === from) return [];
    goal = best;
  }

  const path: number[] = [];
  for (let at = goal; at !== from; at = previous.get(at) as number) path.unshift(at);
  return path;
}
